namespace AMPMWeb.Data;

public static class SeedDb
{
    // Embedded SQLite DB - base64 encoded
    private const string _b64 = "";
    
    public static void RestoreIfEmpty(string dbPath)
    {
        if (System.IO.File.Exists(dbPath))
        {
            try
            {
                using var conn = new Microsoft.Data.Sqlite.SqliteConnection($"Data Source={dbPath}");
                conn.Open();
                using var cmd = conn.CreateCommand();
                cmd.CommandText = "SELECT COUNT(*) FROM employees";
                var count = (long)cmd.ExecuteScalar()!;
                if (count > 0) return; // Already has data
            }
            catch { }
        }
        
        // Restore from embedded DB
        var bytes = Convert.FromBase64String(_b64);
        System.IO.Directory.CreateDirectory(System.IO.Path.GetDirectoryName(dbPath)!);
        System.IO.File.WriteAllBytes(dbPath, bytes);
        Console.WriteLine("DB restored from embedded backup!");
    }
}
